theme.css:
/* ==== INTERFACE ====
   token  --bg #EFF3F1             画布背景｜青白冷绢底色
   token  --text #18201E           主文本｜深松烟墨色
   token  --muted #546663          次级文字与结构分隔线
   token  --focus #BF3626          操作焦点与激活状态｜校勘朱砂
   token  --accent-ink #2B4B52     比照考订色｜青石文宪蓝
   token  --surface #FCFEFD        卡片底板｜极浅冷白承载面
   token  --tag-bg #E0E7E4         文献引用与标注背景
   token  --fs-h1 34px             页标题
   token  --fs-h2 22px             区块标题
   token  --fs-lead 19px           导语与发问
   token  --fs-body 18px           正文与分析展开
   token  --fs-sec 16px            次级成句说明
   token  --fs-label 15px          图元标签与文献引注
   token  --fs-tick 13px           纯刻度与索引编号
   token  --font-serif             古典正史与文献引文衬线字体
   token  --font-sans              界面控件与分析说明无衬线字体
   版心   1488×844                 #stage 已含 padding
   版式   .focus                   单一主体聚焦
   版式   .split-duo               左右互见比照
   版式   .stack-triptych          三段式文献考证
   材质   汉代松烟墨与校雠朱砂；青白冷绢底色与金石楷宋
   ==== /INTERFACE ==== */

:root {
  --bg: #EFF3F1;
  --text: #18201E;
  --muted: #546663;
  --focus: #BF3626;
  --accent-ink: #2B4B52;
  --surface: #FCFEFD;
  --tag-bg: #E0E7E4;

  --font-serif: "Songti SC", "Source Han Serif CN", "STSong", "SimSun", serif;
  --font-sans: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
  --font-display: "Kaiti SC", "STKaiti", "KaiTi", "Source Han Serif CN", serif;

  --fs-h1: 34px;
  --fs-h2: 22px;
  --fs-lead: 19px;
  --fs-body: 18px;
  --fs-sec: 16px;
  --fs-label: 15px;
  --fs-tick: 13px;

  --pad-x: 56px;
  --pad-y: 28px;
}

#stage {
  display: flex;
  flex-direction: column;
  padding: var(--pad-y) var(--pad-x);
  background-color: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  width: 1600px;
  height: 900px;
  box-sizing: border-box;
}

/* 共享版式关系 */
.focus {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: stretch;
}

.split-duo {
  flex: 1;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  align-items: stretch;
}

.stack-triptych {
  flex: 1;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  align-items: stretch;
}

svg .bar, svg .cell, svg .box {
  width: auto;
  height: auto;
}
